export async function test_backend_public_customer_journey(connection: api.IConnection): Promise<void> {
  const customerConnection: api.IConnection = { host: connection.host };
  const email = `journey-customer-${Date.now()}-${Math.random().toString(36).slice(2)}@example.com`;
  const password = "correct-horse-battery-staple";
  const authorized = await api.functional.shopping.auth.customer.join.customerJoin(customerConnection, { email, password });
  typia.assert(authorized);
  if (authorized.customer.email !== email) throw new Error("Customer registration did not return the canonical identity.");
  customerConnection.headers = { Authorization: `Bearer ${authorized.accessToken}` };
  const profile = await api.functional.shopping.customer.profile.read.profile(customerConnection);
  if (profile.id !== authorized.customer.id) throw new Error("Customer profile escaped its owning identity.");
  const edited = await api.functional.shopping.customer.profile.update.profileUpdate(customerConnection, { displayName: "Journey Customer", phoneNumber: "010-0000-0000" });
  if (edited.displayName !== "Journey Customer") throw new Error("Customer profile update was not visible.");
  const address = await api.functional.shopping.customer.address.create.addressCreate(customerConnection, { recipientName: "Journey Customer", recipientPhone: "010-0000-0000", streetAddress: "1 Evidence Road", city: "Seoul", stateOrProvince: "Seoul", postalCode: "00000", country: "KR", isDefault: true });
  const listedAddresses = await api.functional.shopping.customer.address.list.addressIndex(customerConnection, { page: 1, limit: 20 });
  if (!listedAddresses.data.some((item) => item.id === address.id && item.isDefault)) throw new Error("Created default address was not listed as owned.");
  await api.functional.shopping.customer.address._default.addressDefault(customerConnection, address.id);
  const changedAddress = await api.functional.shopping.customer.address.update.addressUpdate(customerConnection, address.id, { recipientName: "Updated Journey Customer", recipientPhone: "010-0000-0001", streetAddress: "2 Evidence Road", city: "Seoul", stateOrProvince: "Seoul", postalCode: "00001", country: "KR", isDefault: true });
  if (changedAddress.streetAddress !== "2 Evidence Road") throw new Error("Address update was not visible.");
  const cart = await api.functional.shopping.customer.cart.read.cart(customerConnection);
  if (cart.lines.length !== 0 || cart.total !== 0) throw new Error("A newly registered customer did not start with an empty cart.");
  const categories = await api.functional.shopping.category.list.categoryIndex(customerConnection, { page: 1, limit: 20 });
  if (categories.pagination.current !== 1) throw new Error("Category pagination was not returned.");
  const products = await api.functional.shopping.product.search.productIndex(customerConnection, { page: 1, limit: 20, sort: "newest" });
  if (products.pagination.current !== 1) throw new Error("Product pagination was not returned.");
  const orders = await api.functional.shopping.customer.order.list.orderIndex(customerConnection, { page: 1, limit: 20 });
  if (orders.pagination.current !== 1) throw new Error("Order history pagination was not returned.");
  await TestValidator.error("missing wishlist product", async () => api.functional.shopping.customer.wishlist.create.wishlistCreate(customerConnection, typia.random<api.IShoppingWishlist.ICreate>()));
  const recovery = await api.functional.shopping.customer.recover.request.recover(customerConnection, { email: `unknown-${Date.now()}@example.com` });
  typia.assert(recovery);
  typia.assert(await api.functional.shopping.customer.password.update.passwordUpdate(customerConnection, { currentPassword: password, newPassword: "new-correct-horse" }));
  const relogged = await api.functional.shopping.auth.customer.login.customerLogin({ host: connection.host }, { email, password: "new-correct-horse" });
  typia.assert(relogged);
  const freshConnection: api.IConnection = { host: connection.host, headers: { Authorization: `Bearer ${relogged.accessToken}` } };
  await api.functional.shopping.customer.address._delete.addressErase(freshConnection, address.id);
  await api.functional.shopping.auth.customer.logout.customerLogout(freshConnection);
}
